/**
 * Excerpt helpers for the activity feed.
 */

export function slugify(text) {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/gu, '-')
    .replace(/^-|-$/gu, '')
}

export function truncate(text, max) {
  if (text.length <= max) return text
  return text.slice(0, max) + '…'
}

